// Reference solution
function redact(value, allow) {
  function walk(v) {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === 'object') {
      var out = {};
      Object.keys(v).forEach(function (k) { out[k] = allow.indexOf(k) >= 0 ? walk(v[k]) : '[redacted]'; });
      return out;
    }
    return v;
  }
  return walk(value);
}

