/** ⇒ [{ line, rule, preview }] */
function scanSecrets(text) {
  // Write your solution here
  var found = [];
  text.split('\n').forEach(function (line, i) {
    var m = line.match(/lfid_key_\w+/);
    if (m) found.push({ line: i, rule: 'labflow-id-secret', preview: m[0] });
  });
  return found;
}

